-- SuperPrecios QRO — datos semilla
-- GENERADO POR scripts/generate-seed.mjs — no editar a mano.
-- Fuente: js/data.js + data/prices.json (2026-08-29T22:48:19.996Z)

begin;

-- Cadenas
on conflict (id) do update set
  name = excluded.name, short_name = excluded.short_name, color = excluded.color,
  accent_color = excluded.accent_color, logo_text = excluded.logo_text,
  search_url_template = excluded.search_url_template;

-- Sucursales de Querétaro
on conflict (id) do update set
  name = excluded.name, zone = excluded.zone, postal_code = excluded.postal_code;

-- Categorías
on conflict (id) do update set name = excluded.name, icon = excluded.icon;

-- Productos del catálogo
on conflict (ean) do update set
  slug = excluded.slug, name = excluded.name, category_id = excluded.category_id,
  unit = excluded.unit, pack_amount = excluded.pack_amount, pack_unit = excluded.pack_unit,
  aliases = excluded.aliases, official_registry_url = excluded.official_registry_url;

-- Precios iniciales (la captura manual con la que arrancó el proyecto).
-- Se insertan como observaciones históricas, igual que lo hará el scraper.
on conflict do nothing;

commit;
